# Vertical reading and right-strip trailing spaces
def printVertically(s):
    words = s.split(' ')
    maxlen = max(len(w) for w in words)
    res = []
    for i in range(maxlen):
        chars = []
        for w in words:
            if i < len(w):
                chars.append(w[i])
            else:
                chars.append(' ')
        res.append(''.join(chars).rstrip())
    return res
